  const resolveCreds = async () => {
    const cred = ctx.get('credentials') // 每次现取（服务可能后于本插件激活）
    let id = cfg.id || ''
    let secret = raw.secret || ''
    if (!secret && raw.secretEnv) secret = process.env[raw.secretEnv] || ''
    if (cred) {
