      if (!id || !secret) {
        if (bot) stopBot()
        log.warn(
          `凭据未就绪（${reason}），机器人未启动——请在「设置 → 插件 → QQ 机器人」填写 AppID / AppSecret，保存后自动生效`,
        )
        return
